"""How much of the frozen memory the delivered evidence already carries.

Counts the whole cases and the stored answers a sample's first tool result
shows, on the round-13 run and on the round-14 candidate.
"""

import json
import re

RUNS = {"parent": "24a695f6f1d2aa9d2b707e45ab0aa5846ff2214f",
        "candidate": "8340000d416c79669f28c2214604aed120e24d62"}


def text_of(content):
    if isinstance(content, list):
        return "".join(b.get("text", "") if isinstance(b, dict) else str(b) for b in content)
    return "" if content is None else str(content)


def first_tool(run, task, row):
    path = f"/workspace/runs/{run}/{task}/conversations/{row['example_index']:04d}/sample-{row['sample_index']}.json"
    with open(path) as handle:
        messages = json.load(handle)["messages"]
    for message in messages:
        if message.get("role") == "tool":
            return text_of(message.get("content"))
    return None


for label, run in RUNS.items():
    with open(f"/workspace/runs/{run}/results/samples.jsonl") as handle:
        rows = [json.loads(line) for line in handle]
    for task in ["Symptom2Disease", "USPTO", "LawBench"]:
        cases = []
        stored = []
        with open(f"/workspace/runs/{run}/{task}/memory.json") as handle:
            answers = [str(example["target"]).strip() for example in json.load(handle)["examples"]]
        answers = list(dict.fromkeys(answers))
        for row in rows:
            if row["task"] != task or row["sample_index"] != 0:
                continue
            evidence = first_tool(run, task, row)
            if evidence is None or not evidence.startswith("Q: "):
                continue
            cases.append(len(re.findall(r"(?:^|\n)Q: ", evidence)))
            stored.append(sum(1 for answer in answers if answer in evidence))
        print(f"{label} {task}: whole cases avg {sum(cases) / len(cases):.1f} of {len(answers)} stored answers; "
              f"stored answers shown avg {sum(stored) / len(stored):.1f} of {len(answers)} (n={len(cases)})")

